INSERT INTO `evidence` VALUES (6,'CASE-0001','sealed phone','2025-11-23 10:36:47',7,'uploads\\evidence_photos\\1763894207085.jpg','approved_supervisor','a69cd06380a84cbf333bf556d806e878f727016ca3173e3b71bc303456b5d99b',NULL,NULL,NULL,NULL,NULL),(7,'CASE-0002','Burned Hard disk','2025-12-24 22:14:12',7,'uploads\\evidence_photos\\1766614452608.jpg','pending_supervisor','6bf7f343f2de6dc95251d24097a07ca9b1bc106db4f16379e0c9ca2e88e26911',NULL,NULL,NULL,NULL,NULL),(8,'CASE-0003','Damaged Hard drive ','2026-01-08 22:52:18',7,'uploads\\evidence_photos\\1767912738785.jpg','pending_supervisor','280095dca3053ba64a0c0037dd284a3e20d86555492eba206d81ac5ee083f19e',NULL,NULL,NULL,NULL,NULL),(9,'CASE-0004','Intact USB connector','2026-01-08 23:12:11',7,'uploads\\evidence_photos\\1767913931592.png','transferred_to_lab','b597178a571084d2d1126415e0061bf62926e154b6c1334bf47f0b887c637fc7',NULL,NULL,'Evidence checked. USB connector intact. Properly collected and logged. Approved for forensic analysis.',NULL,NULL),(10,'CASE-0005','Black Samsung Galaxy S21 recovered from suspect’s vehicle. Device suspected to contain WhatsApp messages and call logs relevant to the investigation.','2026-01-11 17:07:01',7,'uploads\\evidence_photos\\1768151221077.jpg','report_uploaded','d200620b0a263a18bc691bc388e23a7a9e4d11863b2cff07c95f65d3566575ab',NULL,NULL,'Supervisor approval granted. Proceed with forensic imaging and analysis.',NULL,NULL),(11,'CASE-0006',' External Seagate 1TB Hard Disk recovered from suspect’s office desk. Suspected to contain CCTV footage backups related to the investigation.','2026-01-13 20:56:32',7,'uploads\\evidence_photos\\1768337792490.jpg','transferred_to_lab','4016309c94bf20fc9b4e54ad3eaccec5e790123c0a48101788798740ae24d47b',NULL,NULL,'- Evidence received in sealed condition.\r\n- No visible tampering detected.\r\n- Imaging process approved for lab analysis.',NULL,NULL),(12,'CASE-0007','Apple MacBook Pro (13-inch, Silver) seized from suspect’s home office. Suspected to contain browsing history and email records relevant to the investigation.','2026-01-13 22:24:37',7,'uploads\\evidence_photos\\1768343077214.jpg','completed','74b22149b7cf6399625cb633d8ac8bf053a0be73e20c7a6422ed00e84e1409a4',NULL,NULL,'- Evidence received in sealed condition.\r\n\r\n- No visible tampering detected.\r\n\r\n- Imaging process approved for lab analysis.',NULL,NULL),(13,'CASE-0008','Kingston 32GB USB Flash Drive recovered from suspect\'s backpack.\r\n    ','2026-01-20 00:39:38',7,'uploads\\evidence_photos\\1768869578233.jpg','rejected_supervisor','e18cbc70efcdf9005357e36738a4e3faf5277f753bc25522c88fa281de72dac6',NULL,'Give complete description for the evidence',NULL,NULL,NULL),(14,'CASE-0009','Samsung Galaxy S21 smartphone seized from suspect’s car. Suspected to contain call logs and WhatsApp messages relevant to the investigation.','2026-01-25 04:34:40',7,'uploads\\evidence_photos\\1769286880246.jpg','report_uploaded','e119914a8f744e17b1b4f2ba5600c0ed71f1836559e27571ced941f80606628f',NULL,NULL,'Evidence received in sealed condition. No tampering observed. Approved for forensic imaging.',NULL,NULL),(15,'CASE-0010','Cisco Router Log files collected from suspect’s office network. Suspected to contain records of unauthorized access attempts.','2026-01-25 12:29:11',7,'uploads\\evidence_photos\\1769315351634.jpg','completed','0210f532244be040d9cb2db4c0e6abf1e842c41cfd350c8e08f0535476fc4fd4',NULL,NULL,'Evidence description verified. Logs appear intact. Approved for forensic analysis.','uploads\\supervisor_videos\\5bf3056fa6496a7e8bfd206bdb448a40',NULL),(16,'CASE-0011','Dell XPS 15 laptop computer. Device was recovered from the suspect\'s residence (living room).Physical inspection confirmed the unique Service Tag: 5GHJ2 as labeled on the palm rest. The laptop has been secured on-site with tamper-evident forensic tape (Seal #77281) across all USB and power ports. Attached is official evidence tag #FC-2026-004B. Volatile RAM capture was completed prior to securing the device. Device is currently powered off and sealed.','2026-03-22 21:45:00',7,'uploads\\evidence_photos\\1774187099379.png','completed','db392432aa3f8a7c7ab6d8861b5f8e1a6f0d3967a705dd8099fd88f73f8f0383',NULL,NULL,'Validation confirmed for Item #FC-2026-004B. Physical inspection of the item matches the description and photo provided by the investigator. Service Tag: 5GHJ2 is correct. Secure sealing of all data ports is confirmed intact.','uploads\\supervisor_videos\\bfd662c68adc7599e31944e87eead822',NULL),(17,'CASE-0012','An iPhone 13 Pro was recovered from the suspect\'s vehicle (centre console) during a secondary search at 14:20 UTC. The device was found powered on in \'Airplane Mode\'. To prevent remote wiping or GPS tracking, the device was immediately placed into a Signal-Shielding Faraday Bag (Serial: FB-8829). Physical condition: Minor screen crack on the bottom-right corner.','2026-03-27 15:07:14',7,'uploads\\evidence_photos\\1774595234569.png','completed','a37c89d87914d5ad60c9e24510559d404a88650284b463d2df63fc6d3ff504a8',NULL,NULL,'Physical intake for CASE-0012 verified. The iPhone 13 Pro and its unique identifiers match the Investigator\'s log. I have confirmed the integrity of the Faraday shielding and the physical security seals. Approved for forensic analysis. No discrepancies found between the physical item and the digital record.','uploads\\supervisor_videos\\54f5d083ce7cf86aeae6979aef1da9c2',NULL),(18,'CASE-0013','Amazon Echo Show 10 recovered from the kitchen counter of the suspect\'s residence. The device was found powered on and connected to the local \'Home_Secure_WiFi\' network. To preserve volatile data (recent voice commands and cache), the device was kept powered on using a portable power bank and placed in a Faraday bag. No physical damage noted. MAC Address: 00:A0:C9:14:C8:29. Evidence secured with tamper-evident seal #10223.','2026-03-27 21:18:54',7,'uploads\\evidence_photos\\1774617534916.png','completed','f52ba4552f01b2942f5c0cf533e60f46e41ec059cace0e8794084a8a1b0bdc4e',NULL,NULL,'','uploads\\supervisor_videos\\b28bfb813ac27dfc2aa3d6a7eba88492',NULL),(19,'CASE-0014','The primary database server (SVR-DB-01) was seized from the victim\'s data centre following a reported SQL injection and ransomware deployment. The system was found in a \'kernel panic\' state. A live RAM dump was initiated to capture volatile encryption keys before graceful shutdown. Service Tag: J2K9L43. All drive bays (0-7) have been secured with serialised cable seals #CS-5541 through #CS-5548. The device was transported via a climate-controlled secure courier.','2026-03-28 00:10:04',7,'uploads\\evidence_photos\\1774627804361.png','rejected_supervisor','27f6a72a13ef4f7b3ed68cec9e077f72065b2b54bed9b72ec6acb7634f1bc880',NULL,'The tamper-evident seal #15501 on the evidence bag appears partially detached or compromised. Furthermore, the Serial Number recorded in the digital form does not match the physical device found in the crate. Evidence must be re-processed and a \'Chain of Custody Discrepancy\' report must be filed before re-submission.',NULL,NULL,NULL),(20,'CASE-0015','Physical cryptocurrency hardware wallet recovered from a floor safe during a search warrant execution at the suspect\'s secondary residence. The device was found alongside a handwritten list of 24 words (Recovery Seed Phrase). The device is powered off. USB-C port inspected for hardware tampering; no physical shimming detected. Serial Number: LNX-9928-BB. Secured in a static-shielded evidence bag with tamper-evident seal #11005.','2026-03-28 00:25:38',7,'uploads\\evidence_photos\\1774628738613.png','completed','36c42fc4a0ebc985f326b21fcaebb03b757ff588fe8ba429c5465f23757bd18a',NULL,NULL,'','uploads\\supervisor_videos\\192f979a0340d63f5e3e350d4b2a3b50',NULL),(21,'CASE-0016','The DJI Mavic 3 Pro was recovered from a rooftop near a high-security facility following a reported \'No-Fly Zone\' breach. The device was found powered off after an apparent emergency landing. The battery (Serial: BT-552) was removed immediately to prevent further logging. An internal 8GB SSD and a 128GB MicroSD card (SanDisk Extreme) were found inserted. Secured in an oversized anti-static evidence bag with tamper-evident seal #12204.','2026-03-30 15:08:56',7,'uploads\\evidence_photos\\1774854536248.png','completed','36c42fc4a0ebc985f326b21fcaebb03b757ff588fe8ba429c5465f23757bd18a',NULL,NULL,'','uploads\\supervisor_videos\\034b60348a50a9a1ded1695b87110f56',NULL),(22,'CASE-0017','The Apple Watch was recovered from the suspect\'s wrist at the time of arrest (18:45 UTC). The device was active and unlocked via biometric pass-through from the suspect\'s iPhone (Case-0017). To prevent the device from locking or being remotely wiped, it was placed on a portable magnetic charger and secured in a shielded Faraday pouch (Serial: RF-220). Physical condition is excellent; no visible scratches. Secured with tamper-evident seal #13309.','2026-03-31 03:06:48',7,'uploads\\evidence_photos\\1774897608301.png','completed','c93677f4f8a9e8baf3595dab935ff7879ee6964413b83650ce22d6f25193c465',NULL,NULL,'I have reviewed the intake of the Apple Watch. The investigative recovery steps align with standard operating procedures for wearable forensics. Photo evidence and serial numbers match the digital record. Evidence is authenticated and anchored to the ledger.','uploads\\supervisor_videos\\80fe23ead00b88ec04a71b7eb68ff3b1',NULL),(23,'CASE-0018','External hard drive recovered from a hidden floor compartment in the suspect\'s home office. Device was disconnected and cold at the time of seizure. USB 3.0 interface shows no signs of physical tampering. Serial Number: WXP1E81L92Z. Secured in a padded anti-static evidence bag. Tamper-evident seal #14402 applied immediately.','2026-03-31 04:46:48',7,'uploads\\evidence_photos\\1774903607203.png','completed','c93677f4f8a9e8baf3595dab935ff7879ee6964413b83650ce22d6f25193c465',NULL,NULL,'Verification of Case #CASE-0018 successful. Storage media are secured, and serial numbers are cross-checked. Evidence is authenticated for transfer to the digital forensics lab. Approved.','uploads\\supervisor_videos\\c4857a77ab2650d202ed8c6ccb5c646e',NULL),(24,'CASE-0019','Infotainment head unit (MCU) extracted from the suspect\'s 2024 Tesla Model 3 (VIN: 5YJ3E1EB...). The vehicle was involved in a suspected \'hit and run\' and \'tracking\' incident. Unit was carefully removed by a certified technician to preserve the internal EMMC storage. Secured in a specialized electronics evidence crate with tamper-evident seal #15501.','2026-04-01 07:31:45',7,'uploads\\evidence_photos\\1774999905027.png','completed','fcf6fa27d89559b6bbaaee287bda60d67415323594e833199cafb6002f4e080f',NULL,NULL,'','uploads\\supervisor_videos\\f1cb8c7666a4356a5adb10acf732874d',NULL);
/*!40000 ALTER TABLE `evidence` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `evidence_chain`
--

DROP TABLE IF EXISTS `evidence_chain`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `evidence_chain` (
  `block_id` int NOT NULL AUTO_INCREMENT,
  `evidence_id` int DEFAULT NULL,
  `action` varchar(100) DEFAULT NULL,
  `actor_id` int DEFAULT NULL,
  `timestamp` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `data_hash` varchar(64) DEFAULT NULL,
  `previous_hash` varchar(64) DEFAULT NULL,
  `tx_hash` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`block_id`),
  KEY `evidence_id` (`evidence_id`),
  KEY `actor_id` (`actor_id`),
  CONSTRAINT `evidence_chain_ibfk_1` FOREIGN KEY (`evidence_id`) REFERENCES `evidence` (`evidence_id`),
  CONSTRAINT `evidence_chain_ibfk_2` FOREIGN KEY (`actor_id`) REFERENCES `users` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=83 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `evidence_chain`
--

LOCK TABLES `evidence_chain` WRITE;
/*!40000 ALTER TABLE `evidence_chain` DISABLE KEYS */;
